  const hook = args[0] === 'hook' || args[0] === 'git-hook' || (args[0] === 'lsp' && args[1] === 'hook');
  const how = pin.source ? `git clone --branch v${pin.version} ${pin.source} ~/.ai-app-factory/versions/${pin.version}` : 'set FACTORY_HOME to a checkout of the factory';
  console.error(`factory: the engine${pin.version ? ` (version ${pin.version})` : ''} is not installed on this machine. Install it: ${how}`);
  // A hook must never break an agent's turn or a git command because of a missing install.
  process.exit(hook ? 0 : 127);
