const result = spawnSync(process.execPath, [path.join(engine, 'bin', 'factory.mjs'), ...args], { stdio: 'inherit', env: { ...process.env, FACTORY_HOME: engine } });
process.exit(result.status ?? (result.signal ? 1 : 0));
